CREATE TABLE "Estimate" ("id" UUID NOT NULL,"organizationId" UUID NOT NULL,"projectId" UUID NOT NULL,"number" TEXT NOT NULL,"title" TEXT NOT NULL,"currency" TEXT NOT NULL DEFAULT 'VND',"currentVersion" INTEGER NOT NULL DEFAULT 1,"status" TEXT NOT NULL DEFAULT 'DRAFT',"createdBy" UUID NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Estimate_pkey" PRIMARY KEY ("id"));
CREATE TABLE "EstimateVersion" ("id" UUID NOT NULL,"estimateId" UUID NOT NULL,"version" INTEGER NOT NULL,"status" TEXT NOT NULL DEFAULT 'DRAFT',"exchangeRate" DECIMAL(20,6) NOT NULL DEFAULT 1,"subtotalCost" DECIMAL(20,2) NOT NULL DEFAULT 0,"subtotalSelling" DECIMAL(20,2) NOT NULL DEFAULT 0,"assumptions" JSONB,"submittedAt" TIMESTAMP(3),"approvedAt" TIMESTAMP(3),"approvedBy" UUID,"createdBy" UUID NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "EstimateVersion_pkey" PRIMARY KEY ("id"));
CREATE TABLE "EstimateLineItem" ("id" UUID NOT NULL,"estimateVersionId" UUID NOT NULL,"section" TEXT NOT NULL,"itemType" TEXT NOT NULL,"productId" UUID,"customDescription" TEXT,"supplierId" UUID,"quantity" DECIMAL(20,3) NOT NULL,"unit" TEXT NOT NULL,"listPrice" DECIMAL(20,2) NOT NULL DEFAULT 0,"supplierDiscount" DECIMAL(9,4) NOT NULL DEFAULT 0,"netPurchasePrice" DECIMAL(20,2) NOT NULL DEFAULT 0,"currency" TEXT NOT NULL,"exchangeRateSnapshot" DECIMAL(20,6) NOT NULL DEFAULT 1,"baseCostVnd" DECIMAL(20,2) NOT NULL DEFAULT 0,"freightEstimate" DECIMAL(20,2) NOT NULL DEFAULT 0,"taxEstimate" DECIMAL(20,2) NOT NULL DEFAULT 0,"installationCost" DECIMAL(20,2) NOT NULL DEFAULT 0,"otherCost" DECIMAL(20,2) NOT NULL DEFAULT 0,"totalCost" DECIMAL(20,2) NOT NULL DEFAULT 0,"markup" DECIMAL(9,4) NOT NULL DEFAULT 0,"margin" DECIMAL(9,4) NOT NULL DEFAULT 0,"sellingPrice" DECIMAL(20,2) NOT NULL DEFAULT 0,"notes" TEXT,"sourceDocument" TEXT,"position" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "EstimateLineItem_pkey" PRIMARY KEY ("id"));
CREATE TABLE "EstimateApproval" ("id" UUID NOT NULL,"estimateVersionId" UUID NOT NULL,"actorId" UUID NOT NULL,"role" TEXT,"decision" TEXT NOT NULL,"comment" TEXT,"version" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "EstimateApproval_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Quotation" ("id" UUID NOT NULL,"organizationId" UUID NOT NULL,"projectId" UUID NOT NULL,"estimateId" UUID,"number" TEXT NOT NULL,"currency" TEXT NOT NULL,"currentVersion" INTEGER NOT NULL DEFAULT 1,"status" TEXT NOT NULL DEFAULT 'DRAFT',"createdBy" UUID NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Quotation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "QuotationVersion" ("id" UUID NOT NULL,"quotationId" UUID NOT NULL,"version" INTEGER NOT NULL,"status" TEXT NOT NULL DEFAULT 'DRAFT',"validityDate" TIMESTAMP(3),"paymentTerms" TEXT,"deliveryTerms" TEXT,"warrantyTerms" TEXT,"subtotal" DECIMAL(20,2) NOT NULL DEFAULT 0,"discount" DECIMAL(20,2) NOT NULL DEFAULT 0,"tax" DECIMAL(20,2) NOT NULL DEFAULT 0,"grandTotal" DECIMAL(20,2) NOT NULL DEFAULT 0,"acceptedAt" TIMESTAMP(3),"createdBy" UUID NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "QuotationVersion_pkey" PRIMARY KEY ("id"));
CREATE TABLE "QuotationLine" ("id" UUID NOT NULL,"quotationVersionId" UUID NOT NULL,"section" TEXT NOT NULL,"description" TEXT NOT NULL,"quantity" DECIMAL(20,3) NOT NULL,"unit" TEXT NOT NULL,"unitPrice" DECIMAL(20,2) NOT NULL,"lineTotal" DECIMAL(20,2) NOT NULL,"position" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "QuotationLine_pkey" PRIMARY KEY ("id"));
